/* Additional minimal singleflight-style example (Node.js) to avoid cache stampede */
const inflight = new Map();
async function getWithSingleflight(key, loader) {
  if (inflight.has(key)) return await inflight.get(key);
  const p = (async () => {
    try {
      const result = await loader();
      return result;
    } finally {
      inflight.delete(key);
    }
  })();
  inflight.set(key, p);
  return await p;
}

// Usage with cache-aside:
async function getUser(id) {
  const key = `user:${id}`;
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);
  return await getWithSingleflight(key, async () => {
    const user = await db.query('SELECT * FROM users WHERE id=$1', [id]);
    if (user) await redis.set(key, JSON.stringify(user), 'EX', 300);
    return user;
  });
}
